local config = {
  str_homestory_N19chuanshanjia_90010101_1_dialog_content = "Cloud Gardens tem estado bem animado ultimamente.",
  str_homestory_N19chuanshanjia_90010101_2_dialog_content = "Certo? Parece que há muito mais animais aqui do que antes.",
  str_homestory_N19chuanshanjia_90010101_3_dialog_content = "Mas você sabe, eu ainda estou curioso sobre aquela criatura de armadura escamosa que todos falam. Como se chamava de novo?",
  str_homestory_N19chuanshanjia_90010101_4_dialog_content = "o <color=#FFB400>Pangalo lítico</color>?",
  str_homestory_N19chuanshanjia_90010101_5_dialog_content = "Sim!",
  str_homestory_N19chuanshanjia_90010101_6_dialog_content = "Eles parecem ser capazes de cavar através das montanhas e do solo. Fascinante.",
  str_homestory_N19chuanshanjia_90010101_7_dialog_content = "Que som é esse?",
  str_homestory_N19chuanshanjia_90010101_8_dialog_content = "Dessa maneira!",
  str_homestory_N19chuanshanjia_90010101_9_dialog_content = "Coberto de escamas da cabeça aos pés, com uma cauda enorme... Seria um Pangalo bem na nossa frente?!",
  str_homestory_N19chuanshanjia_90010101_10_dialog_content = "Olá.",
  str_homestory_N19chuanshanjia_90010101_11_dialog_content = "Vocês dois estão familiarizados com este lugar, por acaso? Hmm, de acordo com meus anos de conhecimento e experiência...",
  str_homestory_N19chuanshanjia_90010101_12_dialog_content = "Eu só posso supor que você está no comando aqui, sim?",
  str_homestory_N19chuanshanjia_90010101_13_dialog_content = "Como você sabia?",
  str_homestory_N19chuanshanjia_90010101_14_dialog_content = "E-Espere, Vice, Você pode ouvir seus pensamentos, também?",
  str_homestory_N19chuanshanjia_90010101_15_dialog_content = "O que você quer dizer com \"pensamentos\"? Está claramente falando conosco...",
  str_homestory_N19chuanshanjia_90010101_16_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010101_17_dialog_content = "<size=65>Oh meu Deus está falando!</size>",
  str_homestory_N19chuanshanjia_90010101_18_dialog_content = "Estou falando sim.",
  str_homestory_N19chuanshanjia_90010101_19_dialog_content = "E para constar, meu nome é <color=#FFB400>Sahn</color>. Por favor, evite se referir a mim como \"isso\" de agora em diante, obrigado.",
  str_homestory_N19chuanshanjia_90010101_20_dialog_content = "Ah! Seu nome é Sahn!",
  str_homestory_N19chuanshanjia_90010101_21_dialog_content = "Isso é \"dele\", não \"seu\"! Suspiro, posso dizer que você é jovem para sua espécie, mas, por favor, mostre um pouco mais de respeito aos mais velhos.",
  str_homestory_N19chuanshanjia_90010101_22_dialog_content = "Eu sinto muito. A julgar pela sua barba longa e espessa, tenho certeza de que você tem anos de sabedoria e experiência para compartilhar.",
  str_homestory_N19chuanshanjia_90010101_23_dialog_content = "Um animal que pode falar... Poderia ser um desses <color=#FFB400>semi-humanos</color> das lendas?",
  str_homestory_N19chuanshanjia_90010101_24_dialog_content = "Legendas?",
  str_homestory_N19chuanshanjia_90010101_25_dialog_content = "O que aconteceu com os demi-humanos?",
  str_homestory_N19chuanshanjia_90010101_26_dialog_content = "*Tosse* Er, você terá que perdoar meu amigo, Sahn. Acho que é só porque faz muito tempo que ela não vê um Pangalo lítico.",
  str_homestory_N19chuanshanjia_90010101_27_dialog_content = "Sério? Porque ela parece bastante chocada com a noção de um animal falante, se você me perguntar!",
  str_homestory_N19chuanshanjia_90010101_28_dialog_content = "W-Nós conhecemos muitos animais falantes! Certo, Vice?",
  str_homestory_N19chuanshanjia_90010101_29_dialog_content = "Hã?",
  str_homestory_N19chuanshanjia_90010101_30_dialog_content = "(Eu não acho que Sahn saiba que os demi-humanos não estão mais por perto...)",
  str_homestory_N19chuanshanjia_90010101_31_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010101_32_dialog_content = "Ah! R-Certo!",
  str_homestory_N19chuanshanjia_90010101_33_dialog_content = "Você acha que eu nasci ontem? É muito óbvio que ela hesitou agora mesmo!",
  str_homestory_N19chuanshanjia_90010101_34_dialog_content = "Er, sim, bem... É um prazer conhecê-lo, Sahn. Meu nome é Vice, e isso é PlayerName.",
  str_homestory_N19chuanshanjia_90010101_35_dialog_content = "Ele está no comando aqui, e nunca mentiria para você.",
  str_homestory_N19chuanshanjia_90010101_36_dialog_content = "Os animais falantes que ele mencionou são nossos amigos.",
  str_homestory_N19chuanshanjia_90010101_37_dialog_content = "Se você ainda não está convencido, então PlayerName só vai ter que trazê-los para você ver.",
  str_homestory_N19chuanshanjia_90010101_38_dialog_content = "Deixa eu pensar...",
  str_homestory_N19chuanshanjia_90010101_39_dialog_content = "(eu não vi <color=#FFB400>Korgon</color> perto da borda da floresta antes? Eu posso trazê-lo aqui!)",
  str_homestory_N19chuanshanjia_90010101_40_dialog_content = "Ah! S-Sim! Por favor, espere aqui por um momento, Sahn!",
  str_homestory_N19chuanshanjia_90010101_41_dialog_content = "(Não diga nada sobre os demi-humanos enquanto eu estiver fora, entendeu?)",
  str_homestory_N19chuanshanjia_90010101_42_dialog_content = "(O-Claro! Apenas volte logo, ok?)",
  str_homestory_N19chuanshanjia_90010111_1_dialog_content = "Vamos encontrá-lo. Chop-chop!",
  str_homestory_N19chuanshanjia_90010102_1_dialog_content = "Ei! Korgon!",
  str_homestory_N19chuanshanjia_90010102_2_dialog_content = "Ei! Eu só estava procurando por você, chefe!",
  str_homestory_N19chuanshanjia_90010102_3_dialog_content = "Quantas vezes eu tenho que dizer para você parar de me chamar de \"chefe\"?",
  str_homestory_N19chuanshanjia_90010102_4_dialog_content = "Ah! Boa, chefe! De qualquer forma, você tem alguma coisa boa <color=#FFB400>madeira</color> em suas mãos?",
  str_homestory_N19chuanshanjia_90010102_5_dialog_content = "Madeira?",
  str_homestory_N19chuanshanjia_90010102_6_dialog_content = "Eles estão pensando em construir um pequeno porto na Ilha Sharkfang. Dessa forma, eles não terão que ficar arrastando barcos para a praia o tempo todo.",
  str_homestory_N19chuanshanjia_90010102_7_dialog_content = "Você com certeza está ocupado. Mas vamos colocar esse negócio de madeira em espera por um segundo.",
  str_homestory_N19chuanshanjia_90010102_8_dialog_content = "Eu quero te apresentar a alguém primeiro. Você não precisa falar muito, e tente não assustá-lo nem nada.",
  str_homestory_N19chuanshanjia_90010102_9_dialog_content = "Conhecer alguém? Não é um problema! Mas esta madeira não vai se juntar, chefe... Vamos fazer isso amanhã, sim?",
  str_homestory_N19chuanshanjia_90010102_10_dialog_content = "Amanhã? Isso não vai dar, eu...",
  str_homestory_N19chuanshanjia_90010102_11_dialog_content = "Suspiro... Tudo bem, eu te ajudo a juntar um pouco de madeira. Quanto você precisa?",
  str_homestory_N19chuanshanjia_90010102_12_dialog_content = "<color=#FFB400>10</color> pedaços deles devem fazê-lo. Eu vou pagar por eles também, então não se preocupe!",
  str_homestory_N19chuanshanjia_90010102_13_dialog_content = "Agora mesmo!",
  str_homestory_N19chuanshanjia_90010112_1_dialog_content = "10 registros são suficientes.",
  str_homestory_N19chuanshanjia_90010103_1_dialog_content = "Você juntou madeira suficiente?",
  str_homestory_N19chuanshanjia_90010103_2_dialog_content = "Isso deve ajudar! ({1}/{2})",
  str_homestory_N19chuanshanjia_90010103_3_dialog_content = "Esse é o chefe para você! Eu mesma não poderia ter feito melhor!",
  str_homestory_N19chuanshanjia_90010103_4_dialog_content = "Agora, quando você o conhecer, tente não dizer nada de estranho. Apenas sorria e acene com a cabeça na maior parte do tempo e ficaremos bem.",
  str_homestory_N19chuanshanjia_90010103_5_dialog_content = "Você continua falando sobre esse cara, mas ainda não me disse quem ele é, chefe! Ele não é algum tipo de esquisito, é?",
  str_homestory_N19chuanshanjia_90010103_6_dialog_content = "Você sabe que eu não falo com ESSES tipos de pessoas há anos, chefe...",
  str_homestory_N19chuanshanjia_90010103_7_dialog_content = "Ele é um animal que fala a nossa língua, só não o assuste e estaremos bem.",
  str_homestory_N19chuanshanjia_90010103_8_dialog_content = "Tudo o que estou dizendo é que sempre que você abre a boca para falar, seus dentes afiados podem ser um pouco... desanimadores.",
  str_homestory_N19chuanshanjia_90010103_9_dialog_content = "Sim, sim, eu entendo sua deriva, chefe.",
  str_homestory_N19chuanshanjia_90010103_10_dialog_content = "Ainda não.",
  str_homestory_N19chuanshanjia_90010104_1_dialog_content = "Voltei!",
  str_homestory_N19chuanshanjia_90010104_2_dialog_content = "Ah, graças a Deus! Eu estava ficando sem coisas para falar. Ele continua fazendo todos os tipos de perguntas... Eu quase não consegui mais manter a fachada.",
  str_homestory_N19chuanshanjia_90010104_3_dialog_content = "Olha, Sahn!",
  str_homestory_N19chuanshanjia_90010104_4_dialog_content = "Saudações!",
  str_homestory_N19chuanshanjia_90010104_5_dialog_content = "H-Ele vai me comer vivo!!",
  str_homestory_N19chuanshanjia_90010104_6_dialog_content = "PlayerName... Por que você teve que trazer aquele cara, de todas as pessoas?!",
  str_homestory_N19chuanshanjia_90010104_7_dialog_content = "O que você quer dizer com \"aquele cara\"?!",
  str_homestory_N19chuanshanjia_90010104_8_dialog_content = "Vocês esqueceram que eu sou vegetariano? A única coisa que vejo quando olho para um animal pequeno é algo para acariciar e dar guloseimas!",
  str_homestory_N19chuanshanjia_90010104_9_dialog_content = "Não é minha culpa eu ter nascido com uma boca grande cheia de dentes afiados!",
  str_homestory_N19chuanshanjia_90010104_10_dialog_content = "M-Minhas desculpas, amigo. Fui muito rápido em julgá-lo pela sua aparência...",
  str_homestory_N19chuanshanjia_90010104_11_dialog_content = "Por mais aterrorizante que seu sorriso possa ser, devo dizer... Seus dentes são alguns dos mais brilhantes e brancos que eu já vi!",
  str_homestory_N19chuanshanjia_90010104_12_dialog_content = "R-Sério? Finalmente, alguém que aprecia meus dentes!",
  str_homestory_N19chuanshanjia_90010104_13_dialog_content = "Meus dentes de tubarão se substituem com frequência. Eu posso esmagar meus dentes velhos em pó e dar de presente para você usar para cozinhar!",
  str_homestory_N19chuanshanjia_90010104_14_dialog_content = "Th-Isso não será necessário, obrigado...",
  str_homestory_N19chuanshanjia_90010104_15_dialog_content = "De qualquer forma, sinta-se à vontade para visitar a Ilha Sharkfang a qualquer momento!",
  str_homestory_N19chuanshanjia_90010104_16_dialog_content = "A paisagem é a melhor por lá, principalmente durante o dia, quando o sol brilha nas ondas.",
  str_homestory_N19chuanshanjia_90010104_17_dialog_content = "Ah, mas temo que também deva recusar seu gracioso convite. Veja, nossa espécie... é particularmente avessa a grandes massas de água.",
  str_homestory_N19chuanshanjia_90010104_18_dialog_content = "Estamos muito mais em casa nas montanhas. Se desejar visitar-nos no futuro, pode encontrar-nos aqui.",
  str_homestory_N19chuanshanjia_90010104_19_dialog_content = "Decidimos vir aqui para uma visita porque estamos isolados nas montanhas há muito tempo. Meus companheiros de clã queriam ver o mundo exterior.",
  str_homestory_N19chuanshanjia_90010104_20_dialog_content = "Eu só espero que este lugar seja mais pacífico que os outros... Meus companheiros de clã e eu passamos por tantas dificuldades...",
  str_homestory_N19chuanshanjia_90010104_21_dialog_content = "Então é por isso que vocês sempre fogem à primeira vista de outras espécies!",
  str_homestory_N19chuanshanjia_90010104_22_dialog_content = "Posso garantir que Cloud Gardens é perfeitamente seguro.",
  str_homestory_N19chuanshanjia_90010104_23_dialog_content = "Então voltarei aos meus companheiros de clã e falarei a eles sobre este lugar imediatamente!",
  str_homestory_N19chuanshanjia_90010104_24_dialog_content = "E-Espere! Não cheguei a tocar na sua balança!",
  str_homestory_N19chuanshanjia_90010104_25_dialog_content = "Tenho certeza que você terá outra chance algum dia, Korgon.",
  str_homestory_N19chuanshanjia_90010104_26_dialog_content = "Mas primeiro, você terá que deixar esse seu sorriso de lado...",
  str_homestory_N19chuanshanjia_90010104_27_dialog_content = "... Realmente não é minha culpa, você sabe.",
  str_homestory_N19chuanshanjia_90010201_1_dialog_content = "Hum? Você não é Sahn, é?",
  str_homestory_N19chuanshanjia_90010201_2_dialog_content = "Eep! Eu estou <color=#FFB400>Jiji</color>, portador da faixa de cabeça mais resistente e confortável de toda a terra!",
  str_homestory_N19chuanshanjia_90010201_3_dialog_content = "Sahn nos contou sobre seus modos pacíficos e amigáveis, então eu vim imediatamente!",
  str_homestory_N19chuanshanjia_90010201_4_dialog_content = "Diga-me, o que você acha da minha bandana? Eep!",
  str_homestory_N19chuanshanjia_90010201_5_option_content = "É legal.",
  str_homestory_N19chuanshanjia_90010201_6_dialog_content = "Que resposta fria...",
  str_homestory_N19chuanshanjia_90010201_7_option_content = "É fantástico!",
  str_homestory_N19chuanshanjia_90010201_8_dialog_content = "É muito feminino.",
  str_homestory_N19chuanshanjia_90010201_9_dialog_content = "É o meu bem mais precioso! Basta olhar para este artesanato! Esta qualidade!",
  str_homestory_N19chuanshanjia_90010201_10_dialog_content = "A-De qualquer forma... Agora que você está aqui, há algo que eu possa ajudá-lo?",
  str_homestory_N19chuanshanjia_90010201_11_dialog_content = "Eep! Sim, realmente! Acabei de inventar uma piada novinha em folha, e vim compartilhar com vocês!",
  str_homestory_N19chuanshanjia_90010201_12_dialog_content = "Afinal, eu sou o gênio da comédia entre os Pangalos!",
  str_homestory_N19chuanshanjia_90010201_13_dialog_content = "Meu sonho é me tornar o maior comediante do mundo, para que eu possa espalhar alegria desenfreada e risadas arrebatadoras para todos!",
  str_homestory_N19chuanshanjia_90010201_14_dialog_content = "Uma piada? Ok, vamos ouvir!",
  str_homestory_N19chuanshanjia_90010201_15_dialog_content = "Muito bem, então! Mantenha seus ouvidos abertos, prepare-se para isso! Eep!",
  str_homestory_N19chuanshanjia_90010201_16_dialog_content = "Há muito, muito tempo atrás, havia um bravo guerreiro.",
  str_homestory_N19chuanshanjia_90010201_17_dialog_content = "Sua lâmina estava fria, suas mãos estavam frias, seu coração estava frio, sua personalidade estava fria como um pepino... Na verdade, toda a sua existência estava fria como gelo.",
  str_homestory_N19chuanshanjia_90010201_18_dialog_content = "E no final, ela congelou até a morte.",
  str_homestory_N19chuanshanjia_90010201_19_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010201_20_dialog_content = "<size=65>Hahahahaha!</size>",
  str_homestory_N19chuanshanjia_90010201_21_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010201_22_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010201_23_dialog_content = "<size=65>Ahaha.</size>",
  str_homestory_N19chuanshanjia_90010201_24_dialog_content = "Eep! Seu rosto não me engana! Essa foi a risada mais forçada que eu já ouvi na minha vida!",
  str_homestory_N19chuanshanjia_90010201_25_dialog_content = "Er... E-Isso é porque meu senso de humor é muito estranho! Por que você não tenta contar a outra pessoa sua piada?",
  str_homestory_N19chuanshanjia_90010201_26_dialog_content = "V-é melhor você não estar mentindo para mim!",
  str_homestory_N19chuanshanjia_90010201_27_dialog_content = "Eu não sou, honesto! acho que me lembro de ter visto Revy por aqui em algum lugar... Perfeito!",
  str_homestory_N19chuanshanjia_90010202_1_dialog_content = "Ei, Revy? Parece que você está se distanciando.",
  str_homestory_N19chuanshanjia_90010202_2_dialog_content = "Estou contando as folhas de grama no chão.",
  str_homestory_N19chuanshanjia_90010202_3_dialog_content = "E-eu vejo... De qualquer forma, tenho alguém aqui que quer te contar uma piada, e acho que você ia gostar muito. Interessado?",
  str_homestory_N19chuanshanjia_90010202_4_dialog_content = "Ah, claro.",
  str_homestory_N19chuanshanjia_90010202_5_dialog_content = "Eep! Maravilhoso! Ela parece alguém que pode apreciar um pouco de humor seco!",
  str_homestory_N19chuanshanjia_90010202_6_dialog_content = "Estou ouvindo.",
  str_homestory_N19chuanshanjia_90010202_7_dialog_content = "Há muito, muito tempo atrás, havia um bravo guerreiro.",
  str_homestory_N19chuanshanjia_90010202_8_dialog_content = "Sua lâmina estava fria, suas mãos estavam frias, seu coração estava frio, sua personalidade estava fria como um pepino... Na verdade, toda a sua existência estava fria como gelo.",
  str_homestory_N19chuanshanjia_90010202_9_dialog_content = "E no final, ela congelou até a morte.",
  str_homestory_N19chuanshanjia_90010202_10_dialog_content = "Ah.",
  str_homestory_N19chuanshanjia_90010202_11_dialog_content = "Eep! E-Isso é tudo que você tem a dizer?!",
  str_homestory_N19chuanshanjia_90010202_12_dialog_content = "(Droga! Parece que nem Revy riria de uma piada dessas...)",
  str_homestory_N19chuanshanjia_90010202_13_dialog_content = "S-Desculpe, Jiji! Deixe-me ir encontrar outra pessoa! Afinal, Revy estava ocupado com algo realmente importante agora.",
  str_homestory_N19chuanshanjia_90010202_14_dialog_content = "Não é mesmo, Revy?",
  str_homestory_N19chuanshanjia_90010202_15_dialog_content = "Hã?",
  str_homestory_N19chuanshanjia_90010202_16_dialog_content = "Vamos lá! Não vá a lugar nenhum, Jiji! Encontrarei o público perfeito para sua piada, prometo!",
  str_homestory_N19chuanshanjia_90010203_1_dialog_content = "Você é o único aqui?",
  str_homestory_N19chuanshanjia_90010203_2_dialog_content = "O que você quer dizer com isso?",
  str_homestory_N19chuanshanjia_90010203_3_dialog_content = "Você só... Não parece do tipo que gosta de piadas, só isso.",
  str_homestory_N19chuanshanjia_90010203_4_dialog_content = "Algo sobre uma lâmina fria e um coração frio...",
  str_homestory_N19chuanshanjia_90010203_5_dialog_content = "Uma \"lâmina fria\"? O que você está falando?",
  str_homestory_N19chuanshanjia_90010203_6_dialog_content = "Hum? Dayna!",
  str_homestory_N19chuanshanjia_90010203_7_dialog_content = "Hahaha! Você está falando sério?!",
  str_homestory_N19chuanshanjia_90010203_8_dialog_content = "Você está rindo?",
  str_homestory_N19chuanshanjia_90010203_9_dialog_content = "É essa a sua ideia de piada, Boatscrapper?",
  str_homestory_N19chuanshanjia_90010203_10_dialog_content = "N-Não, não é minha piada. Outra pessoa veio com ele.",
  str_homestory_N19chuanshanjia_90010203_11_dialog_content = "Bem, leve-me até eles! Acontece que estou livre agora.",
  str_homestory_N19chuanshanjia_90010211_1_dialog_content = "Faça isso, barqueiro!",
  str_homestory_N19chuanshanjia_90010204_1_dialog_content = "Sua? Mas ela não parece do tipo que entende piadas...",
  str_homestory_N19chuanshanjia_90010204_2_dialog_content = "Você está brincando comigo? Eu ouvi todos os tipos de piadas em Umbraton!",
  str_homestory_N19chuanshanjia_90010204_3_dialog_content = "Eep! Então vamos tentar. Ouça com atenção, agora!",
  str_homestory_N19chuanshanjia_90010204_4_dialog_content = "Há muito, muito tempo atrás, havia um bravo guerreiro. Sua lâmina estava fria...",
  str_homestory_N19chuanshanjia_90010204_5_dialog_content = "Oh, entendi.",
  str_homestory_N19chuanshanjia_90010204_6_dialog_content = "Você não parece particularmente entusiasmado.",
  str_homestory_N19chuanshanjia_90010204_7_dialog_content = "Não desista, Jiji! Continue!",
  str_homestory_N19chuanshanjia_90010204_8_dialog_content = "Suas mãos estavam frias...",
  str_homestory_N19chuanshanjia_90010204_9_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010204_10_dialog_content = "Seu coração estava frio.",
  str_homestory_N19chuanshanjia_90010204_10X1_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010204_10X2_dialog_content = "Na verdade, todo o seu corpo estava frio como gelo.",
  str_homestory_N19chuanshanjia_90010204_10X3_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010204_11_dialog_content = "... Affff.",
  str_homestory_N19chuanshanjia_90010204_12_dialog_content = "E no final, ela congelou até a morte.",
  str_homestory_N19chuanshanjia_90010204_13_dialog_content = "<size=65>Hahahahaha! Essa piada foi seca!</size>",
  str_homestory_N19chuanshanjia_90010204_14_dialog_content = "<size=65>O que?!?</size>",
  str_homestory_N19chuanshanjia_90010204_15_dialog_content = "Sua entrega poderia dar algum trabalho, mas a piada foi sólida! Eu precisava de uma boa risada!",
  str_homestory_N19chuanshanjia_90010204_16_dialog_content = "Estou feliz que alguém finalmente encontrou o humor nele!",
  str_homestory_N19chuanshanjia_90010204_17_dialog_content = "Com piadas como essa, você poderia fazer alguns fãs em Umbraton!",
  str_homestory_N19chuanshanjia_90010204_18_dialog_content = "Você provavelmente até se tornaria famoso.",
  str_homestory_N19chuanshanjia_90010204_19_dialog_content = "Ei!!! R-Sério? Eu deveria ir contar aos meus companheiros de clã!",
  str_homestory_N19chuanshanjia_90010204_20_dialog_content = "Hahahahaha! Essa piada foi tão seca! E tão engraçado!",
  str_homestory_N19chuanshanjia_90010204_21_dialog_content = "eu deveria perguntar PlayerName para contar de novo quando eu tiver a chance.",
  str_homestory_N19chuanshanjia_90010301_1_dialog_content = "<size=65>Gwa! Eu finalmente encontrei você!</size>",
  str_homestory_N19chuanshanjia_90010301_2_dialog_content = "Outro Pangalo, hein? E este não parece muito feliz... Você por acaso é amigo de Sahn e Jiji?",
  str_homestory_N19chuanshanjia_90010301_3_dialog_content = "Gwa! Você deve ser PlayerName! Eu sou <color=#FFB400>Atarracado</color>, e vim em busca de vingança!",
  str_homestory_N19chuanshanjia_90010301_4_dialog_content = "Por sua causa, Jiji me enrolou e me chutou como uma bola!",
  str_homestory_N19chuanshanjia_90010301_5_dialog_content = "E-Espere, então você não deveria estar se vingando de Jiji, não de mim?",
  str_homestory_N19chuanshanjia_90010301_6_dialog_content = "Gwa! Ela disse que só fez isso porque você mentiu para ela!",
  str_homestory_N19chuanshanjia_90010301_7_dialog_content = "Jiji veio correndo até mim, dizendo uma coisa ou outra sobre uma \"lâmina fria\" e \"mãos frias\"...",
  str_homestory_N19chuanshanjia_90010301_8_dialog_content = "\"E então ela congelou até a morte.\"",
  str_homestory_N19chuanshanjia_90010301_9_dialog_content = "Gwa! Exatamente! Que piada sem graça.",
  str_homestory_N19chuanshanjia_90010301_10_dialog_content = "Mas ela continuou insistindo que era a piada mais engraçada do mundo, e que você tinha atestado!",
  str_homestory_N19chuanshanjia_90010301_11_dialog_content = "Ela ficou furiosa quando descobriu que na verdade era uma piada horrível, e que você mentiu para ela sobre isso!",
  str_homestory_N19chuanshanjia_90010301_12_dialog_content = "E então ela me transformou em uma bola de chute.",
  str_homestory_N19chuanshanjia_90010301_13_dialog_content = "Ela me chutou por tanto tempo, o mundo ainda está girando diante dos meus olhos.",
  str_homestory_N19chuanshanjia_90010301_14_dialog_content = "Então pensei comigo mesmo, se foi você quem começou tudo isso... Então você deveria ser o punido, não eu!",
  str_homestory_N19chuanshanjia_90010301_15_dialog_content = "P-Punição?",
  str_homestory_N19chuanshanjia_90010301_16_dialog_content = "Gwa! Isso mesmo! Você deve se enrolar em uma bola e deixá-la chutá-lo em vez disso!",
  str_homestory_N19chuanshanjia_90010301_17_dialog_content = "Que tipo de lógica é essa...?",
  str_homestory_N19chuanshanjia_90010301_18_dialog_content = "Bem, você tem alguma idéia melhor?",
  str_homestory_N19chuanshanjia_90010301_19_dialog_content = "Se você tivesse sido honesto com Jiji sobre sua piada desde o início, nada disso estaria acontecendo.",
  str_homestory_N19chuanshanjia_90010301_20_dialog_content = "M-Mas todo mundo tem seu próprio senso de humor...",
  str_homestory_N19chuanshanjia_90010301_21_dialog_content = "Eu acho que dar incentivo ao Jiji é importante!",
  str_homestory_N19chuanshanjia_90010301_22_dialog_content = "Pode não ter sido tão engraçado quanto ela esperava, mas às vezes uma pequena mentira... quero dizer, ainda era bem engraçado! E Jiji precisa do nosso apoio!",
  str_homestory_N19chuanshanjia_90010301_23_dialog_content = "Jiji? Gwaaaa! E quanto a mim?! Basta olhar para a forma em que estou!",
  str_homestory_N19chuanshanjia_90010301_24_dialog_content = "Estou enrolada há tanto tempo que não consigo mais endireitar minhas costas!",
  str_homestory_N19chuanshanjia_90010301_25_dialog_content = "O que eu preciso, é um pouco de alimentação!",
  str_homestory_N19chuanshanjia_90010301_26_dialog_content = "\"Alimentação\"...? Você quer dizer comida?",
  str_homestory_N19chuanshanjia_90010301_27_dialog_content = "Correto! Algo <color=#FFB400>doce</color> funcionaria melhor, eu acho.",
  str_homestory_N19chuanshanjia_90010301_28_dialog_content = "Sobremesas, hein? acho que vi um <color=#FFB400>Comerciante Chubb</color> indo em direção à floresta... Vamos dar uma olhada.",
  str_homestory_N19chuanshanjia_90010311_1_dialog_content = "Você encontrará algo doce, não é?",
  str_homestory_N19chuanshanjia_90010302_1_dialog_content = "Sobremesas? Tudo fora. Chubb.",
  str_homestory_N19chuanshanjia_90010302_2_dialog_content = "Tudo fora?",
  str_homestory_N19chuanshanjia_90010302_3_dialog_content = "Este não é um balcão único para todas as suas necessidades de lanches! Você tem que fazer um pedido primeiro! Chubb!",
  str_homestory_N19chuanshanjia_90010302_4_dialog_content = "Fazer um pedido...?",
  str_homestory_N19chuanshanjia_90010302_5_dialog_content = "Chubb! Isso mesmo! Ver? <color=#FFB400>Vice</color> tem uma encomenda de bolo aqui mesmo!",
  str_homestory_N19chuanshanjia_90010302_6_dialog_content = "Vice! É claro! Você sabe onde ela está?",
  str_homestory_N19chuanshanjia_90010302_7_dialog_content = "Pelo Rio. Chubb!",
  str_homestory_N19chuanshanjia_90010302_8_dialog_content = "Obrigado! Chubb!",
  str_homestory_N19chuanshanjia_90010302_9_dialog_content = "Não mencione isso! Chubb!",
  str_homestory_N19chuanshanjia_90010302_10_dialog_content = "Hã?",
  str_homestory_N19chuanshanjia_90010312_1_dialog_content = "Pelo Rio. Vice, Chubb.",
  str_homestory_N19chuanshanjia_90010303_1_dialog_content = "Ei, Vice? O que é isso na sua cara...?",
  str_homestory_N19chuanshanjia_90010303_2_dialog_content = "Hã?",
  str_homestory_N19chuanshanjia_90010303_3_dialog_content = "Você não estava comendo bolo agora, estava?",
  str_homestory_N19chuanshanjia_90010303_4_dialog_content = "Como você sabia?",
  str_homestory_N19chuanshanjia_90010303_5_dialog_content = "Argh, cheguei tarde!",
  str_homestory_N19chuanshanjia_90010303_6_dialog_content = "Culpado, hehe... Você realmente queria tanto um bolo assim?",
  str_homestory_N19chuanshanjia_90010303_7_dialog_content = "É uma longa história... Eu só preciso de um bolo agora, mesmo que seja um pedaço pequeno.",
  str_homestory_N19chuanshanjia_90010303_8_dialog_content = "Quando fui pegar meu bolo, vi <color=#FFB400>Korgon</color> fazer um pedido para alguns, também. Mas não faço ideia para quê...",
  str_homestory_N19chuanshanjia_90010303_9_dialog_content = "Mas eu o vi fazendo o seu caminho para <color=#FFB400>Praça Jacinto</color> depois.",
  str_homestory_N19chuanshanjia_90010303_10_dialog_content = "Praça Jacinto, hein? Entendi!",
  str_homestory_N19chuanshanjia_90010313_1_dialog_content = "Apresse-se agora! Ou ele vai terminar de comer!",
  str_homestory_N19chuanshanjia_90010304_1_dialog_content = "Ei! Eu finalmente encontrei você!",
  str_homestory_N19chuanshanjia_90010304_2_dialog_content = "E aí, chefe?",
  str_homestory_N19chuanshanjia_90010304_3_dialog_content = "Ainda tem bolo?",
  str_homestory_N19chuanshanjia_90010304_4_dialog_content = "Oh? Eu não sabia que você gostava de doces, chefe?",
  str_homestory_N19chuanshanjia_90010304_5_dialog_content = "Ah! Sim eu fiz.",
  str_homestory_N19chuanshanjia_90010304_6_dialog_content = "Huh? Não, isso não pode estar certo. Lembro-me de você me dizendo que não se importa com doces.",
  str_homestory_N19chuanshanjia_90010304_7_dialog_content = "Você está certo, mas... É uma longa história.",
  str_homestory_N19chuanshanjia_90010304_8_dialog_content = "Não se preocupe, chefe! Eu compreendo totalmente! Todo homem tem seus próprios segredos...",
  str_homestory_N19chuanshanjia_90010304_9_dialog_content = "E se meu palpite estiver certo... eu diria que você tem um bichinho para alimentar, não é?",
  str_homestory_N19chuanshanjia_90010304_10_dialog_content = "H-Huh? Er, quero dizer... Sim, sim, eu quero...",
  str_homestory_N19chuanshanjia_90010304_11_dialog_content = "De qualquer forma, você acha que poderia poupar um pedacinho de bolo...?",
  str_homestory_N19chuanshanjia_90010304_12_dialog_content = "Sem problemas!",
  str_homestory_N19chuanshanjia_90010314_1_dialog_content = "Não é muito, mas deve ser o suficiente. O que você diz, chefe?",
  str_homestory_N19chuanshanjia_90010305_1_dialog_content = "Voltei! E eu trouxe bolo!",
  str_homestory_N19chuanshanjia_90010305_2_dialog_content = "Espera!",
  str_homestory_N19chuanshanjia_90010305_3_dialog_content = "O que foi?",
  str_homestory_N19chuanshanjia_90010305_4_dialog_content = "Este bolo não foi devidamente <color=#FFB400>temperado</color>, tem?",
  str_homestory_N19chuanshanjia_90010305_5_dialog_content = "\"Temperado\"...?",
  str_homestory_N19chuanshanjia_90010305_6_dialog_content = "Enquanto a doçura de um bolo é muitas vezes o sabor principal, há outro tempero que é tão importante quanto!",
  str_homestory_N19chuanshanjia_90010305_7_dialog_content = "De que tipo de tempero você está falando? Acho que não vai ser fácil encontrar ingredientes prontos por aqui...",
  str_homestory_N19chuanshanjia_90010305_8_dialog_content = "Não há necessidade, temos muito aqui!",
  str_homestory_N19chuanshanjia_90010305_9_dialog_content = "Aqui onde?",
  str_homestory_N19chuanshanjia_90010305_10_dialog_content = "O solo abaixo de nós, é claro.",
  str_homestory_N19chuanshanjia_90010305_11_dialog_content = "S-solo...?!",
  str_homestory_N19chuanshanjia_90010305_12_dialog_content = "Nossa espécie cava as montanhas dia após dia e muitas vezes acaba consumindo solo no processo.",
  str_homestory_N19chuanshanjia_90010305_13_dialog_content = "E, claro, diferentes tipos de solo têm sabores diferentes. Pessoalmente, gosto de adicionar uma colher de solo gramado à minha comida para obter um sabor levemente adstringente. Este é o melhor!",
  str_homestory_N19chuanshanjia_90010305_14_dialog_content = "Ah, só de pensar em colocar um pouco nesse pedaço de bolo... Já estou com água na boca!",
  str_homestory_N19chuanshanjia_90010305_15_dialog_content = "O mundo pode ser um lugar muito estranho às vezes...",
  str_homestory_N19chuanshanjia_90010305_16_dialog_content = "De qualquer forma, você tem meus agradecimentos! Agora, vou procurar um solo adequado para este bolo, para que eu possa compartilhar um pouco com Jiji como uma oferta de paz!",
  str_homestory_N19chuanshanjia_90010305_17_dialog_content = "Talvez então eu pudesse convencê-la a me poupar de qualquer outra punição! Gwa!",
  str_homestory_N19chuanshanjia_90010305_18_dialog_content = "Que conjunto de gostos completamente diferente... Embora eu ache que há um bolo para todos lá fora, hein?",
  str_homestory_N19chuanshanjia_90010401_1_dialog_content = "Ouvi dizer que você derrotou o Tubby! Bata-o bem, eu ouvi!",
  str_homestory_N19chuanshanjia_90010401_2_dialog_content = "Vocês com certeza têm talento para interpretar mal os outros...?",
  str_homestory_N19chuanshanjia_90010401_3_dialog_content = "Zé! Tubby saiu furioso alguns dias atrás, dizendo que ia acertar as contas com você! Resolver a pontuação!",
  str_homestory_N19chuanshanjia_90010401_4_dialog_content = "Mas então ele voltou todo feliz e despreocupado! Disse que não fez nada! Nem uma única coisa!",
  str_homestory_N19chuanshanjia_90010401_5_dialog_content = "Você deve ter batido nele bobo! Bateu os miolos dele, não foi?!",
  str_homestory_N19chuanshanjia_90010401_6_dialog_content = "Eu não fiz nada disso! Acabei de dividir um pedaço de bolo com Tubby, só isso!",
  str_homestory_N19chuanshanjia_90010401_7_dialog_content = "Zé! Você deve ser muito lutador! Um guerreiro habilidoso, de fato!",
  str_homestory_N19chuanshanjia_90010401_8_dialog_content = "Eu estou <color=#FFB400>Espalhafatoso</color>. Como um guerreiro de Lithic Pangalos, eu desafio você para a batalha! Batalhar!",
  str_homestory_N19chuanshanjia_90010401_9_dialog_content = "Vocês não ouvem muito o que os outros dizem, não é...?",
  str_homestory_N19chuanshanjia_90010401_10_dialog_content = "Desculpe desapontá-lo, Fussy, mas não sou nem um pouco lutador. Você terá que lutar com outra pessoa.",
  str_homestory_N19chuanshanjia_90010401_11_dialog_content = "Zé? Você não quer lutar comigo?",
  str_homestory_N19chuanshanjia_90010401_12_dialog_content = "Poderia ser... Que você é tão poderoso, você é incapaz de conter seu imenso poder? Que você teme lutar comigo resultará em minha morte horrível?",
  str_homestory_N19chuanshanjia_90010401_13_dialog_content = "Se sim... então envie seu discípulo mais forte para a batalha! Seu melhor discípulo!! Zé!!!",
  str_homestory_N19chuanshanjia_90010401_14_dialog_content = "D-Discípulo...?",
  str_homestory_N19chuanshanjia_90010401_15_dialog_content = "Sim! Se você não vai lutar comigo por medo de me prejudicar, então permita que seu discípulo lute em seu lugar! Zé!",
  str_homestory_N19chuanshanjia_90010401_16_dialog_content = "Vocês REALMENTE não ouvem o que os outros dizem, de jeito nenhum!",
  str_homestory_N19chuanshanjia_90010401_17_dialog_content = "Absurdo! Eu ouvi você alto e claro. Agora mande chamar seu discípulo mais forte! Esperarei aqui na expectativa ansiosa de nossa próxima batalha!",
  str_homestory_N19chuanshanjia_90010401_18_dialog_content = "OK.",
  str_homestory_N19chuanshanjia_90010401_19_dialog_content = "Parece que tenho outro mal-entendido nas mãos... Acho que vou ter que encontrar alguém para lidar com isso.",
  str_homestory_N19chuanshanjia_90010401_20_dialog_content = "Zé! Sobre o que diabos você está murmurando? Diga-me agora!",
  str_homestory_N19chuanshanjia_90010401_21_dialog_content = "Eu disse que ia dar uma volta na beira do rio. Eu volto daqui a pouco.",
  str_homestory_N19chuanshanjia_90010402_1_dialog_content = "O que você está olhando? Chubb.",
  str_homestory_N19chuanshanjia_90010402_2_dialog_content = "Suspiro... Você parece tão lutador quanto eu...",
  str_homestory_N19chuanshanjia_90010402_3_dialog_content = "Nós Chubbs não somos adequados para lutar, não. Chubb.",
  str_homestory_N19chuanshanjia_90010402_4_dialog_content = "Este é um lugar de paz, afinal. Chubb.",
  str_homestory_N19chuanshanjia_90010402_5_dialog_content = "Ei... isso é Barton? O que ele está fazendo aqui? Chubb!",
  str_homestory_N19chuanshanjia_90010402_6_dialog_content = "Ele está pesquisando o terreno em busca de um lugar para construir um campo de treinamento para novos recrutas. Chubb!",
  str_homestory_N19chuanshanjia_90010402_7_dialog_content = "Realmente é ele!",
  str_homestory_N19chuanshanjia_90010402_8_dialog_content = "Ch-Chubb?",
  str_homestory_N19chuanshanjia_90010411_1_dialog_content = "Próximo. Barton, Chubb.",
  str_homestory_N19chuanshanjia_90010403_1_dialog_content = "Podemos compactar a terra aqui para campos de treinamento e lançar as bases para um quartel ali...",
  str_homestory_N19chuanshanjia_90010403_2_dialog_content = "Aí está você, Barton!",
  str_homestory_N19chuanshanjia_90010403_3_dialog_content = "Ah, seu timing não poderia ser melhor! Preciso da sua ajuda com algo, e precisarei comandar esta terra para fazer isso!",
  str_homestory_N19chuanshanjia_90010403_4_dialog_content = "C-Comandante..?",
  str_homestory_N19chuanshanjia_90010403_5_dialog_content = "É muito pacífico aqui, o que simplesmente não serve!",
  str_homestory_N19chuanshanjia_90010403_6_dialog_content = "Vocês são como cordeiros sentados em uma cova de lobos!",
  str_homestory_N19chuanshanjia_90010403_7_dialog_content = "Você precisa de guardas! Você precisa de soldados!",
  str_homestory_N19chuanshanjia_90010403_8_dialog_content = "Então, naturalmente, você precisa de um campo de treinamento em primeiro lugar.",
  str_homestory_N19chuanshanjia_90010403_9_dialog_content = "Deixe para mim! Vou estabelecer este regimento e treiná-los também!",
  str_homestory_N19chuanshanjia_90010403_10_dialog_content = "E acredite em mim, não vou descansar até que o trabalho esteja feito! Dessa forma, os números da minha própria legião podem subir também...",
  str_homestory_N19chuanshanjia_90010403_11_dialog_content = "Tenho certeza que essa é a única razão pela qual você está fazendo isso...",
  str_homestory_N19chuanshanjia_90010403_12_dialog_content = "Não importa, agora não é hora de perguntar sobre isso.",
  str_homestory_N19chuanshanjia_90010403_13_dialog_content = "Você acha que seu acampamento pode esperar um pouco mais, Barton? Tenho alguém aqui que quer testar sua coragem contra você.",
  str_homestory_N19chuanshanjia_90010403_14_dialog_content = "Um novo recruta já veio bater, hein?",
  str_homestory_N19chuanshanjia_90010403_15_dialog_content = "Onde eles estão?",
  str_homestory_N19chuanshanjia_90010403_16_dialog_content = "Logo ali.",
  str_homestory_N19chuanshanjia_90010403_17_dialog_content = "Tudo bem, hora de uma lição de humildade! Talvez então eles pensem duas vezes antes de desafiar o instrutor em seu primeiro dia...",
  str_homestory_N19chuanshanjia_90010403_18_dialog_content = "E-Espere, Barton! Ainda tenho mais para te contar!",
  str_homestory_N19chuanshanjia_90010412_1_dialog_content = "Por que você ainda esta aqui?",
  str_homestory_N19chuanshanjia_90010404_1_dialog_content = "Então você é o pequeno novato tentando criar problemas para nós, não é?",
  str_homestory_N19chuanshanjia_90010404_2_dialog_content = "Zé! Você é ainda mais arrogante do que PlayerName! Muito mais arrogante!",
  str_homestory_N19chuanshanjia_90010404_3_dialog_content = "Presumo que você também seja um lutador habilidoso, certo? Zé!",
  str_homestory_N19chuanshanjia_90010404_4_dialog_content = "Eles já estão ansiosos para lutar! Eu posso praticamente ver as faíscas voando...",
  str_homestory_N19chuanshanjia_90010404_5_dialog_content = "Não preciso ser um lutador habilidoso para colocar um recruta insubordinado em seu lugar!",
  str_homestory_N19chuanshanjia_90010404_6_dialog_content = "Você não parece muito de um lutador. Mas há muitos excêntricos como você aqui nos Jardins das Nuvens.",
  str_homestory_N19chuanshanjia_90010404_7_dialog_content = "Para o inferno com isso! Se seus braços e pernas funcionam bem, e essa sua cauda não é apenas para mostrar, então eu vou fazer de você um soldado ainda!",
  str_homestory_N19chuanshanjia_90010404_8_dialog_content = "Agora, então, que comece o treinamento!",
  str_homestory_N19chuanshanjia_90010404_9_dialog_content = "Como esperado de um verdadeiro discípulo de um mestre! A dureza de suas palavras é tão poderosa quanto a confiança que você exala!",
  str_homestory_N19chuanshanjia_90010404_10_dialog_content = "Mas mesmo assim, você me subestima por sua conta e risco! Chegou a hora de decidir qual de nós é mais forte! Zaaa!",
  str_homestory_N19chuanshanjia_90010404_11_dialog_content = "<size=65>Espere!</size>",
  str_homestory_N19chuanshanjia_90010404_12_dialog_content = "Eu não acho que uma batalha é a maneira certa de fazer isso! Por que vocês dois não...",
  str_homestory_N19chuanshanjia_90010404_13_dialog_content = "Faça um concurso de \"<color=#FFB400>auras</color>,\" em vez de?",
  str_homestory_N19chuanshanjia_90010404_14_dialog_content = "... Zé? \"Auras\"?",
  str_homestory_N19chuanshanjia_90010404_15_dialog_content = "Nossas auras?",
  str_homestory_N19chuanshanjia_90010404_16_dialog_content = "É como... Uma combinação de sua vontade de lutar, seu estado físico e suas capacidades de combate, além de outras coisas.",
  str_homestory_N19chuanshanjia_90010404_17_dialog_content = "Eu sou um celestita, lembra? Posso usar meus poderes para ver suas auras e determinar qual de vocês é mais forte.",
  str_homestory_N19chuanshanjia_90010404_18_dialog_content = "E-Isso é possível?!",
  str_homestory_N19chuanshanjia_90010404_19_dialog_content = "É... Posso atestar a força dos poderes psíquicos dos celestitas. Este método deve funcionar tão bem quanto uma batalha real.",
  str_homestory_N19chuanshanjia_90010404_20_dialog_content = "Vamos lá.",
  str_homestory_N19chuanshanjia_90010404_21_dialog_content = "<anim type=Shake><size=65>Grrrrrr—</size></anim>",
  str_homestory_N19chuanshanjia_90010404_22_dialog_content = "<anim type=Shake><size=65>Zaaaaa—</size></anim>",
  str_homestory_N19chuanshanjia_90010404_23_dialog_content = "O-o que são esses?! Não sei dizer qual é mais forte!",
  str_homestory_N19chuanshanjia_90010404_24_dialog_content = "Ambos são incrivelmente poderosos!!",
  str_homestory_N19chuanshanjia_90010404_25_dialog_content = "Entendi!",
  str_homestory_N19chuanshanjia_90010404_26_dialog_content = "Impressionante!",
  str_homestory_N19chuanshanjia_90010404_27_dialog_content = "Parecia um empate para mim, pessoal.",
  str_homestory_N19chuanshanjia_90010404_28_dialog_content = "(Outro Pangalo, outra mentira...)",
  str_homestory_N19chuanshanjia_90010404_29_dialog_content = "Tenho que dizer, PlayerName, você fez bem em encontrar um novo recruta tão promissor! Você tem meus agradecimentos!",
  str_homestory_N19chuanshanjia_90010404_30_dialog_content = "Illumina poderia usar alguém como você, e você nunca vai querer nada sob minha liderança! O que você diz, meu amigo?",
  str_homestory_N19chuanshanjia_90010404_31_dialog_content = "Zé! Um discípulo com seus próprios discípulos... Na verdade, estou na presença dos mestres!",
  str_homestory_N19chuanshanjia_90010404_32_dialog_content = "Devo voltar para as montanhas e treinar por muitos mais anos, se quiser alcançar essas alturas também! Até o próximo encontro, companheiros guerreiros! Até a próxima!",
  str_homestory_N19chuanshanjia_90010404_33_dialog_content = "E ela mostrou tanta promessa, também! Um dia triste para os militares da Illumina, de fato...",
  str_homestory_N19chuanshanjia_90010404_34_dialog_content = "Uma vez que meu campo de treinamento esteja construído, terei certeza de recrutá-la para minhas fileiras! Até a próxima vez, PlayerName!",
  str_homestory_N19chuanshanjia_90010404_35_dialog_content = "Não acredito... Eles acabaram admirando os pontos fortes um do outro...",
  str_homestory_N19chuanshanjia_90010501_1_dialog_content = "Minha amiga!",
  str_homestory_N19chuanshanjia_90010501_2_dialog_content = "Huh? Você está falando comigo?",
  str_homestory_N19chuanshanjia_90010501_3_dialog_content = "Du-du! Todos falaram da sua ajuda, então eu vim te ver também!",
  str_homestory_N19chuanshanjia_90010501_4_dialog_content = "Deixe-me adivinhar... Seu nome é \"Du-Du\" ou algo assim, certo?",
  str_homestory_N19chuanshanjia_90010501_5_dialog_content = "É na verdade <color=#FFB400>Barriga Verde</color>! Du-du!",
  str_homestory_N19chuanshanjia_90010501_6_dialog_content = "Entendo... Quando você disse \"todos\", você estava se referindo a todos os Pangalos que vieram nos últimos dias?",
  str_homestory_N19chuanshanjia_90010501_7_dialog_content = "De fato! Todos eles sentem um grande sentimento de gratidão por você, então eu vim entregar um sinal dessa gratidão!",
  str_homestory_N19chuanshanjia_90010501_8_dialog_content = "Um sinal de gratidão? Como um presente?",
  str_homestory_N19chuanshanjia_90010501_9_dialog_content = "Du-du! Uma bebida especial, para ser mais preciso! Feito a partir de uma receita secreta de família!",
  str_homestory_N19chuanshanjia_90010501_10_dialog_content = "Pode parecer normal do lado de fora...",
  str_homestory_N19chuanshanjia_90010501_11_dialog_content = "Mas você vai entender o quão especial é no momento em que passa pelos seus lábios! Du-du!",
  str_homestory_N19chuanshanjia_90010501_12_dialog_content = "Parece um pouco quente quando desce pela garganta, mas uma vez que chega à barriga, todo o seu corpo experimentará uma sensação de conforto diferente de tudo que você já sentiu ...",
  str_homestory_N19chuanshanjia_90010501_13_dialog_content = "Parece bem interessante! Existe realmente uma bebida assim no mundo?",
  str_homestory_N19chuanshanjia_90010501_14_dialog_content = "Du-du! Claro que existe! Agora, então, você gostaria de experimentar alguns?",
  str_homestory_N19chuanshanjia_90010501_15_dialog_content = "É claro! O que você precisa para fazer isso?",
  str_homestory_N19chuanshanjia_90010501_16_dialog_content = "Du-du! Como eu disse, é uma receita secreta de família!",
  str_homestory_N19chuanshanjia_90010501_17_dialog_content = "Primeiro, vou precisar de alguns <color=#FFB400>sal</color>.",
  str_homestory_N19chuanshanjia_90010501_18_dialog_content = "acho que vi o <color=#FFB400>Comerciante Chubb</color> vagando perto da floresta. Podemos pedir alguns!",
  str_homestory_N19chuanshanjia_90010511_1_dialog_content = "O tempo está passando. Se apresse! Du-du.",
  str_homestory_N19chuanshanjia_90010502_1_dialog_content = "Sal? Sim eu tenho alguns. Chubb!",
  str_homestory_N19chuanshanjia_90010502_2_dialog_content = "Alguém já fez pedidos de sal. Não posso vendê-lo como desejo, Chubb.",
  str_homestory_N19chuanshanjia_90010502_3_dialog_content = "Eu só preciso de um pouquinho. Você não pode poupar um pouco?",
  str_homestory_N19chuanshanjia_90010502_4_dialog_content = "Deixe-me ver, Chubb.",
  str_homestory_N19chuanshanjia_90010502_5_dialog_content = "Deveria ser bom para você um pouco, pela minha estimativa. Chubb!",
  str_homestory_N19chuanshanjia_90010502_6_dialog_content = "Isso é ótimo!",
  str_homestory_N19chuanshanjia_90010502_7_dialog_content = "Mas você deve fazer a diferença com <color=#FFB400>minério</color>. Preciso aumentar as vendas do minério, Chubb!",
  str_homestory_N19chuanshanjia_90010502_8_dialog_content = "Não é um problema! Podemos negociar!",
  str_homestory_N19chuanshanjia_90010512_1_dialog_content = "Eu disse 10! Chubb!",
  str_homestory_N19chuanshanjia_90010503_1_dialog_content = "Minério suficiente?",
  str_homestory_N19chuanshanjia_90010503_2_dialog_content = "Aqui! Os minérios. ({1}/{2})",
  str_homestory_N19chuanshanjia_90010503_3_dialog_content = "Aquilo foi rápido! Chubb!",
  str_homestory_N19chuanshanjia_90010503_4_dialog_content = "É claro! PlayerName está muito familiarizado com o Cloud Gardens! Chubb!",
  str_homestory_N19chuanshanjia_90010503_5_dialog_content = "Este é o sal. Não o perca. Chubb.",
  str_homestory_N19chuanshanjia_90010503_6_dialog_content = "Tudo bem embalado e firme. Não jogue fora no caminho de volta, Chubb.",
  str_homestory_N19chuanshanjia_90010503_7_dialog_content = "Muito obrigado!",
  str_homestory_N19chuanshanjia_90010503_8_dialog_content = "Ainda não.",
  str_homestory_N19chuanshanjia_90010513_1_dialog_content = "Cuidado para não derramar, Chubb!",
  str_homestory_N19chuanshanjia_90010504_1_dialog_content = "Aqui está o sal.",
  str_homestory_N19chuanshanjia_90010504_2_dialog_content = "Isso levou muito tempo! Du-du!",
  str_homestory_N19chuanshanjia_90010504_3_dialog_content = "Sim, foi um grande desvio. Se não fosse por esta bebida misteriosa...",
  str_homestory_N19chuanshanjia_90010504_4_dialog_content = "Você verá em breve. Eu tenho o resto dos ingredientes prontos para ir, du-du!",
  str_homestory_N19chuanshanjia_90010504_5_dialog_content = "Vamos começar!",
  str_homestory_N19chuanshanjia_90010504_6_dialog_content = "Você vai sair daqui por um segundo. Essa é uma receita secreta, sabe? Exclusivo! Du-du!",
  str_homestory_N19chuanshanjia_90010504_7_dialog_content = "Ah, então deixe-me <color=#FFB400>vá passear em algum lugar perto</color>.",
  str_homestory_N19chuanshanjia_90010504_8_dialog_content = "Vá para uma caminhada mais longa! A beira do rio é bom!",
  str_homestory_N19chuanshanjia_90010505_1_dialog_content = "Você finalmente está aqui! A bebida está pronta!",
  str_homestory_N19chuanshanjia_90010505_2_dialog_content = "Huh? Parece realmente normal. É transparente e também não tem cheiro de nada.",
  str_homestory_N19chuanshanjia_90010505_3_dialog_content = "Eu adicionei um sabor secreto a ele! Um tipo especial! Você não pode vê-lo quando é colocado na água.",
  str_homestory_N19chuanshanjia_90010505_4_dialog_content = "Um aroma que não se vê na água... É aquele saco de sal?",
  str_homestory_N19chuanshanjia_90010505_5_dialog_content = "Eu gosto de pessoas inteligentes! Du-du!",
  str_homestory_N19chuanshanjia_90010505_6_dialog_content = "Ah! Oh não, não é mais um segredo!",
  str_homestory_N19chuanshanjia_90010505_7_dialog_content = "Você está me dizendo que o único tempero nesta bebida misteriosa é o sal?!",
  str_homestory_N19chuanshanjia_90010505_8_dialog_content = "Sua habilidade psíquica faz jus ao que Fussy estava me dizendo. Du-du!",
  str_homestory_N19chuanshanjia_90010505_9_dialog_content = "Na verdade, apenas sal. Du-du.",
  str_homestory_N19chuanshanjia_90010505_10_dialog_content = "<size=65>Não é apenas água salgada então?!</size>",
  str_homestory_N19chuanshanjia_90010505_11_dialog_content = "Shh! Não deixe ninguém ouvir isso! Du-du!",
  str_homestory_N19chuanshanjia_90010505_12_dialog_content = "Se for sal, tem muito à beira-mar!",
  str_homestory_N19chuanshanjia_90010505_13_dialog_content = "Mas não há nenhum nas montanhas! Du-du! Tudo o que você encontra nas montanhas é o tipo de água que é clara e sem sabor.",
  str_homestory_N19chuanshanjia_90010505_14_dialog_content = "Uma vez, eu estava em uma caverna e lambi a água condensada na rocha. Estava salgado.",
  str_homestory_N19chuanshanjia_90010505_15_dialog_content = "Achei esse sabor maravilhoso desde então! Du-du!",
  str_homestory_N19chuanshanjia_90010505_16_dialog_content = "(Bem, o sal é uma coisa comum em nossas vidas.)",
  str_homestory_N19chuanshanjia_90010505_17_dialog_content = "(Mas para eles...)",
  str_homestory_N19chuanshanjia_90010505_18_dialog_content = "Agora que você mencionou, eu percebo isso também.",
  str_homestory_N19chuanshanjia_90010505_19_dialog_content = "O sal tem um sabor verdadeiramente maravilhoso.",
  str_homestory_N19chuanshanjia_90010505_20_dialog_content = "Conte-me sobre isso! Eu! Du-du! Você deve manter isso em segredo!",
  str_homestory_N19chuanshanjia_90010505_21_dialog_content = "Está bem, está bem.",
  str_homestory_N19chuanshanjia_90010505_22_dialog_content = "Eu tenho bastante sal aqui. Você pode passar a qualquer hora e pegar alguns.",
  str_homestory_N19chuanshanjia_90010505_23_dialog_content = "Sério? Isso é generoso de sua parte! Du-du!",
  str_homestory_N19chuanshanjia_90010505_24_dialog_content = "Eu também tenho muitas bebidas em outros sabores que você pode provar na próxima vez.",
  str_homestory_N19chuanshanjia_90010505_25_dialog_content = "Sim! Sim! Mas ainda acho que essa água salgada tem o melhor sabor!",
  str_homestory_N19chuanshanjia_90010505_26_dialog_content = "Se você não está bebendo, então eu vou pegar de volta! Du-du!",
  str_homestory_N19chuanshanjia_90010505_27_dialog_content = "Cuidado aí!",
  str_homestory_N19chuanshanjia_90010505_28_dialog_content = "Sal, hein... Toca um sino naquele provérbio de um romance.",
  str_homestory_N19chuanshanjia_90010505_29_dialog_content = "\"Amar uma pessoa é como salgar. Nem mais nem menos.\"",
  str_homestory_N19chuanshanjia_90010505_30_dialog_content = "Talvez o verdadeiro segredo dessa bebida seja a proporção de sal e água.",
  str_homestory_N19chuanshanjia_90010601_1_dialog_content = "<anim type=Shake><size=65>A morte é o vazio! A morte é a verdade!</size></anim>",
  str_homestory_N19chuanshanjia_90010601_2_dialog_content = "Este lugar é muito barulhento... Vice, Estou indo embora!",
  str_homestory_N19chuanshanjia_90010601_3_dialog_content = "O que é isso? Eu não posso ouvi-lo claramente! Bem, o que quer que você diga, eu tenho que ir!",
  str_homestory_N19chuanshanjia_90010601_4_dialog_content = "Vice, esperar!",
  str_homestory_N19chuanshanjia_90010601_5_dialog_content = "Ela saiu rapidamente. De qualquer forma, a música aqui é alta.",
  str_homestory_N19chuanshanjia_90010601_6_dialog_content = "Argh, eu pensei que seria capaz de lidar Reginadesempenho de agora, mas acho que não.",
  str_homestory_N19chuanshanjia_90010601_7_dialog_content = "Isso conta mesmo como música? São apenas sons estrondosos aleatórios de instrumentos musicais.",
  str_homestory_N19chuanshanjia_90010601_8_dialog_content = "Essa música é um enviado de Deus! Inexistente em todo o mundo selvagem! Eep!",
  str_homestory_N19chuanshanjia_90010601_9_dialog_content = "Este tempo, melodia, arranjo e vocal. Não posso perder! Eep!",
  str_homestory_N19chuanshanjia_90010601_10_dialog_content = "... Você está falando sério?",
  str_homestory_N19chuanshanjia_90010601_11_dialog_content = "Sim, o nome desse músico incrível é Regina.",
  str_homestory_N19chuanshanjia_90010601_12_dialog_content = "Ah! Claro.",
  str_homestory_N19chuanshanjia_90010601_13_dialog_content = "Ela deve ser muito popular.",
  str_homestory_N19chuanshanjia_90010601_14_dialog_content = "É um pouco... Hum, eu não sei como colocar.",
  str_homestory_N19chuanshanjia_90010601_15_dialog_content = "O que você quer dizer? Você não parece gostar da música dela.",
  str_homestory_N19chuanshanjia_90010601_16_dialog_content = "Isso mesmo! Zé!",
  str_homestory_N19chuanshanjia_90010601_17_dialog_content = "Sahn, Jiji, fomos dar uma espiada.",
  str_homestory_N19chuanshanjia_90010601_18_dialog_content = "Regina não tinha plateia! Du!",
  str_homestory_N19chuanshanjia_90010601_19_dialog_content = "Como isso pode...?",
  str_homestory_N19chuanshanjia_90010601_20_dialog_content = "É verdade! Regina estava se apresentando sozinho.",
  str_homestory_N19chuanshanjia_90010601_21_dialog_content = "Que pena... Está longe, mas posso sentir o descontentamento Reginaestá cantando.",
  str_homestory_N19chuanshanjia_90010601_22_dialog_content = "Du-du! Devemos torcer por ela?",
  str_homestory_N19chuanshanjia_90010601_23_dialog_content = "Boa ideia! Eep!",
  str_homestory_N19chuanshanjia_90010601_24_dialog_content = "Mas ela parece um pouco assustadora. Não é uma boa ideia a gente correr até lá, certo? Gwa!",
  str_homestory_N19chuanshanjia_90010601_25_dialog_content = "Vamos praticar como torcer por alguém.",
  str_homestory_N19chuanshanjia_90010601_26_dialog_content = "PlayerName, como os Aurorianos torcem pelos outros?",
  str_homestory_N19chuanshanjia_90010601_27_dialog_content = "Eu... posso perguntar a alguém. Enquanto eu puder sair daqui...",
  str_homestory_N19chuanshanjia_90010601_28_dialog_content = "Vamos esperar para ouvir de você.",
  str_homestory_N19chuanshanjia_90010601_29_dialog_content = "Eu vou <color=#FFB400>vá perguntar Vice</color>. Ela ainda deve estar por perto.",
  str_homestory_N19chuanshanjia_90010602_1_dialog_content = "Ufa, silêncio finalmente.",
  str_homestory_N19chuanshanjia_90010602_2_dialog_content = "Oi, Vice! Eu preciso de algo de você.",
  str_homestory_N19chuanshanjia_90010602_3_dialog_content = "Não me diga que você ainda quer que eu ouça Reginamúsica de!",
  str_homestory_N19chuanshanjia_90010602_4_dialog_content = "N-Não, eu tenho uma pergunta para você.",
  str_homestory_N19chuanshanjia_90010602_5_dialog_content = "Qualquer pergunta está bem, desde que não esteja ouvindo essa música.",
  str_homestory_N19chuanshanjia_90010602_6_dialog_content = "Qual é a melhor maneira de animar alguém? De preferência com muita gente.",
  str_homestory_N19chuanshanjia_90010602_7_dialog_content = "Parece muito com o <color=#FFB400>Apoio, suporte</color> este <color=#FFB400>Barbara</color> mencionado antes.",
  str_homestory_N19chuanshanjia_90010602_8_dialog_content = "Ela acontece de estar pendurada no rio. Quer ir perguntar a ela?",
  str_homestory_N19chuanshanjia_90010602_9_dialog_content = "Isso é ótimo!",
  str_homestory_N19chuanshanjia_90010603_1_dialog_content = "A pesca é tão difícil!",
  str_homestory_N19chuanshanjia_90010603_2_dialog_content = "Oi, Barbara! Sair para passear?",
  str_homestory_N19chuanshanjia_90010603_3_dialog_content = "Eu estou pescando! É uma tarefa bem difícil!",
  str_homestory_N19chuanshanjia_90010603_4_dialog_content = "Estou feliz por estares aqui. Qual é a melhor maneira de apoiar alguém?",
  str_homestory_N19chuanshanjia_90010603_5_dialog_content = "Eu não sei, minha barriga está vazia agora!",
  str_homestory_N19chuanshanjia_90010603_6_dialog_content = "Então é por isso que você está pescando?",
  str_homestory_N19chuanshanjia_90010603_7_dialog_content = "Estou super desejando sashimi! Mas a pesca é tão difícil!",
  str_homestory_N19chuanshanjia_90010603_8_dialog_content = "Não é difícil pescar. Me deixe fazê-lo!",
  str_homestory_N19chuanshanjia_90010603_9_dialog_content = "<color=#FFB400>Três peixes</color> devem ser suficientes, certo?",
  str_homestory_N19chuanshanjia_90010603_10_dialog_content = "Super o suficiente!",
  str_homestory_N19chuanshanjia_90010604_1_dialog_content = "Peixe fresco! Vou pegar peixe fresco!",
  str_homestory_N19chuanshanjia_90010604_2_dialog_content = "Isso é o suficiente, certo? ({1}/{2})",
  str_homestory_N19chuanshanjia_90010604_3_dialog_content = "Sim! Muito fresco!",
  str_homestory_N19chuanshanjia_90010604_4_dialog_content = "Você pode comer o seu preenchimento mais tarde. Você pode responder minha pergunta agora, certo?",
  str_homestory_N19chuanshanjia_90010604_5_dialog_content = "Se eu quiser que várias pessoas torçam por uma pessoa, isso é <color=#FFB400>Apoio, suporte</color>, certo?",
  str_homestory_N19chuanshanjia_90010604_6_dialog_content = "Existe algum truque?",
  str_homestory_N19chuanshanjia_90010604_7_dialog_content = "Seu \"<color=#FFB400>amor</color>\"!",
  str_homestory_N19chuanshanjia_90010604_8_dialog_content = "Amor? Só isso?",
  str_homestory_N19chuanshanjia_90010604_9_dialog_content = "É extremamente importante!",
  str_homestory_N19chuanshanjia_90010604_10_dialog_content = "Se você mostrar amor suficiente, a outra pessoa sentirá isso com certeza.",
  str_homestory_N19chuanshanjia_90010604_11_dialog_content = "Só isso?",
  str_homestory_N19chuanshanjia_90010604_12_dialog_content = "A sinceridade é melhor do que qualquer truque!",
  str_homestory_N19chuanshanjia_90010604_13_dialog_content = "Eu vou tentar...",
  str_homestory_N19chuanshanjia_90010604_14_dialog_content = "Vou pescar um pouco mais.",
  str_homestory_N19chuanshanjia_90010605_1_dialog_content = "Pelo que ouvi, vocês têm que ser sinceros o suficiente para mostrar seu amor... e deve ser isso.",
  str_homestory_N19chuanshanjia_90010605_2_dialog_content = "Mas como expressamos o amor?",
  str_homestory_N19chuanshanjia_90010605_3_dialog_content = "De acordo com os profissionais, a outra parte definitivamente sentirá isso se vocês realmente gostarem deles.",
  str_homestory_N19chuanshanjia_90010605_4_dialog_content = "Você apenas terá que se expressar completamente.",
  str_homestory_N19chuanshanjia_90010605_5_dialog_content = "Falando do amor Regina tem para a música, provavelmente entendemos que o melhor!",
  str_homestory_N19chuanshanjia_90010605_6_dialog_content = "Sim! Esse é o espírito!",
  str_homestory_N19chuanshanjia_90010605_7_dialog_content = "Vou discutir contramedidas com eles. Venha ver nosso suporte depois também!",
  str_homestory_N19chuanshanjia_90010605_8_dialog_content = "Eu tenho que voltar...?",
  str_homestory_N19chuanshanjia_90010606_1_dialog_content = "Meus ouvidos começaram a sangrar assim que voltei aqui.",
  str_homestory_N19chuanshanjia_90010606_2_dialog_content = "<anim type=Shake><size=65>Mundo injusto! Coração em chamas!</size></anim>",
  str_homestory_N19chuanshanjia_90010606_3_dialog_content = "Mas é como o Sahn disse. Seja a letra ou o ritmo, há um sentimento de ressentimento.",
  str_homestory_N19chuanshanjia_90010606_4_dialog_content = "Parece Regina tem muitos pensamentos que ela quer expressar também...",
  str_homestory_N19chuanshanjia_90010606_5_dialog_content = "Você está dizendo...",
  str_homestory_N19chuanshanjia_90010606_6_dialog_content = "Música! Não pare! Eep!",
  str_homestory_N19chuanshanjia_90010606_7_dialog_content = "Zé! Queremos música!",
  str_homestory_N19chuanshanjia_90010606_8_dialog_content = "Reginamúsica de! O mais forte! Du!",
  str_homestory_N19chuanshanjia_90010606_9_dialog_content = "Aqui está a última música! Para todo o novo público!",
  str_homestory_N19chuanshanjia_90010606_10_dialog_content = "<anim type=Shake><size=65>Como a chegada de um grande inimigo!</size></anim>",
  str_homestory_N19chuanshanjia_90010606_11_dialog_content = "<anim type=Shake><size=65>Os verdadeiros inimigos realmente não são Eclipsites!</size></anim>",
